-- Rewrite grade-9 explanations: vague-but-helpful first-sentence hint
UPDATE question_translations SET explanation='Concentrează-te pe ce au în comun cele două fenomene la nivel de forță fundamentală, nu pe rezultatele lor. Aceeași forță (nucleară slabă) stă la baza radioactivității și este implicată în fuziunea din stele.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=1);
UPDATE question_translations SET explanation='Întreabă-te ce o face utilă pentru orientare — strălucirea sau locul ei pe cer. Utilitatea ei vine din poziția aproape fixă pe cer, lângă polul nord ceresc, nu din strălucire.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=2);
UPDATE question_translations SET explanation='Caută o dovadă legată de mișcare: ce fac structurile mari unele față de altele. Expansiunea înseamnă că galaxiile se îndepărtează unele de altele.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=3);
UPDATE question_translations SET explanation='Gândește-te ce distanțe leagă raportul: una e din Sistemul Solar, cealaltă dintre stele. Raportul uriaș arată cât de mari sunt distanțele dintre stele față de distanța Terra–Soare (1 u.a.).' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=4);
UPDATE question_translations SET explanation='Imaginează-ți ce s-ar întâmpla cu numărul dacă ai scrie aceeași distanță în kilometri. Anul-lumină este o unitate potrivită scării cosmice; în kilometri numerele ar fi imense și greu de folosit. (Anul-lumină este o distanță, nu o durată.)' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=5);
UPDATE question_translations SET explanation='Folosește relația dată (1 pc = 3,26 ani-lumină) ca să le ordonezi după mărime. Ordinea crescătoare este: unitatea astronomică < anul-lumină < parsecul.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=6);
UPDATE question_translations SET explanation='Pornește mereu de la materia difuză spre stadiul final și elimină variantele care încep invers. Steaua masivă pornește din nebuloasă, devine stea, apoi gigantă roșie, explodează ca supernovă și ajunge stea neutronică sau gaură neagră.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=7);
UPDATE question_translations SET explanation='Ce însușire a unei stele îi hotărăște soarta finală? Gândește-te la „cât de mare”. Drumul evolutiv depinde de masa stelei: cele mai masive pot sfârși ca gaură neagră.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=8);
UPDATE question_translations SET explanation='Leagă răspunsul de ce conțin nebuloasele și ce se poate forma din acea materie. Nebuloasele sunt aglomerări de gaz și praf cosmic; prin concentrarea materiei se nasc stele.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=9);
UPDATE question_translations SET explanation='Care forță adună materia împrăștiată și o strânge la un loc? Gravitația concentrează materia nebuloasei până se formează o stea.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=10);
UPDATE question_translations SET explanation='Dacă ar lipsi ce ține nucleul unit, ce nivel al materiei s-ar destrăma mai întâi — atomul, planeta sau galaxia? Fără forța nucleară tare, protonii și neutronii nu ar mai fi ținuți împreună, iar nucleele s-ar destrăma.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=11);
UPDATE question_translations SET explanation='Pune accent pe cuvântul „observabil” și pe ce sugerează el despre ce putem vedea. Termenul arată că vedem doar partea din Univers din care lumina a ajuns până la noi.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=12);
UPDATE question_translations SET explanation='Dacă ne aflăm într-un braț al galaxiei, unde nu putem fi în același timp? Brațele sunt la periferie față de nucleu; aflându-ne în brațul Orion, nu suntem în centrul galaxiei.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=13);
UPDATE question_translations SET explanation='Gândește-te din ce loc privim Calea Lactee — dinăuntrul ei sau din afară. Fiind în interiorul galaxiei, privim discul „din muchie”, de aceea apare ca un brâu luminos.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=14);
UPDATE question_translations SET explanation='Leagă „cele mai simple elemente” de un moment timpuriu în evoluția materiei. Hidrogenul și heliul sunt elementele cele mai simple și mai vechi, ceea ce susține rolul stelelor de verigă de bază în evoluția materiei.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=15);
UPDATE question_translations SET explanation='Amintește-ți ce măsoară de fapt anul-lumină înainte de a alege. Anul-lumină este o distanță; un diametru de 100 000 de ani-lumină înseamnă că lumina îl străbate în circa 100 000 de ani.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=16);
UPDATE question_translations SET explanation='Întreabă-te de ce o stea strălucește singură, iar o planetă nu. Stelele eliberează energie prin fuziune nucleară; planetele doar reflectă lumina primită.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=17);
UPDATE question_translations SET explanation='Gândește-te ce rămâne după ce o stea își termină „combustibilul”. Pitica albă este restul dens și fierbinte al unei stele epuizate; se răcește treptat, devenind pitică neagră.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=18);
UPDATE question_translations SET explanation='Dacă electronii n-ar mai fi legați de nucleu, ce structură de bază a materiei ar dispărea? Fără forța electromagnetică, atomii stabili — și deci materia obișnuită — nu ar putea exista.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=19);
UPDATE question_translations SET explanation='Concentrează-te pe sensul cuvântului „continuă”: descrie ceva care se oprește sau care merge mai departe? Cuvântul subliniază o „evoluție continuă”: Universul se schimbă și se extinde în permanență.' WHERE question_id = (SELECT id FROM questions WHERE grade_id='9' AND topic_slug='geografie-fizica' AND position=20);
